"""Integration checks use generated bytes and a loopback seeder, never game downloads."""
import hashlib
import json
import os
from pathlib import Path
import sys
import threading
import time
import unittest
import urllib.request
import urllib.error
import uuid

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
WORK = ROOT / '.test-data' / uuid.uuid4().hex
WORK.mkdir(parents=True)
sys.argv = ['engine.py', '0', str(WORK / 'state')]
import engine
from repair_utils import find_save_path, safe_file
lt = engine.lt


def wait_for(predicate, seconds=35):
    end = time.monotonic() + seconds
    while time.monotonic() < end:
        if predicate():
            return
        time.sleep(.15)
    raise AssertionError('Timed out waiting for engine state')


class EngineTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        engine.ses.apply_settings({'enable_dht': False, 'enable_lsd': False,
                                  'enable_upnp': False, 'enable_natpmp': False,
                                  'allow_multiple_connections_per_ip': True})
        cls.server = engine.HTTPServer(('127.0.0.1', 0), engine.EngineAPI)
        threading.Thread(target=cls.server.serve_forever, daemon=True).start()
        cls.url = 'http://127.0.0.1:' + str(cls.server.server_port)
        cls.seed = lt.session({'listen_interfaces': '127.0.0.1:0', 'enable_dht': False,
                               'enable_lsd': False, 'enable_upnp': False, 'enable_natpmp': False,
                               'allow_multiple_connections_per_ip': True})

    @classmethod
    def tearDownClass(cls):
        cls.server.shutdown()
        cls.server.server_close()
        engine.is_shutting_down = True
        engine.ses.pause()
        cls.seed.pause()

    def api(self, route, body):
        request = urllib.request.Request(self.url + route, data=json.dumps(body).encode(),
                                         headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(request, timeout=35) as response:
            return json.load(response)

    def start_repair(self, body):
        result = self.api('/repair/scan', body)
        wait_for(lambda: engine.torrents[result['id']].get('report') is not None)
        return self.api('/repair/confirm', {'id': result['id']})

    def fixture(self, label, payload=None):
        name = 'Fixture-' + label
        source = WORK / ('seed-' + label)
        folder = source / name
        folder.mkdir(parents=True)
        contents = payload or {'good.bin': os.urandom(65536), 'bad.bin': os.urandom(65536),
                    'nested/missing.bin': os.urandom(65536)}
        storage = lt.file_storage()
        for relative, data in contents.items():
            file = folder / relative
            file.parent.mkdir(parents=True, exist_ok=True)
            file.write_bytes(data)
            storage.add_file(name + '/' + relative, len(data))
        builder = lt.create_torrent(storage, 16384, lt.create_torrent.v1_only)
        lt.set_piece_hashes(builder, str(source))
        ti = lt.torrent_info(builder.generate())
        seed_params = lt.add_torrent_params()
        seed_params.ti = ti
        seed_params.save_path = str(source)
        seed_params.flags &= ~(lt.torrent_flags.paused | lt.torrent_flags.auto_managed)
        seed_handle = self.seed.add_torrent(seed_params)
        wait_for(lambda: seed_handle.status().is_seeding)
        tid = str(ti.info_hash())
        engine.metadata_cache[tid] = ti
        return name, contents, ti, tid, lt.make_magnet_uri(ti)

    def test_01_repair_missing_and_same_size_corruption(self):
        name, contents, ti, tid, magnet = self.fixture('repair')
        parent = WORK / 'library' / 'group'
        game = parent / name
        game.mkdir(parents=True)
        (game / 'good.bin').write_bytes(contents['good.bin'])
        (game / 'bad.bin').write_bytes(b'x' * len(contents['bad.bin']))
        (game / 'personal-save.txt').write_text('keep me')
        good_mtime = (game / 'good.bin').stat().st_mtime_ns
        result = self.start_repair({'magnet': magnet, 'folder': str(parent.parent)})
        self.assertEqual(Path(result['save_path']), parent)
        obj = engine.torrents[tid]
        wait_for(lambda: obj['is_repairing'])
        self.assertFalse(obj['is_verified'])
        self.assertGreater(obj['handle'].status().total_wanted_done, 0)
        obj['handle'].connect_peer(('127.0.0.1', self.seed.listen_port()))
        wait_for(lambda: obj['is_moved'])
        self.assertTrue(obj['is_verified'])
        for relative, data in contents.items():
            self.assertEqual(hashlib.sha256((game / relative).read_bytes()).digest(), hashlib.sha256(data).digest())
        self.assertEqual((game / 'good.bin').stat().st_mtime_ns, good_mtime)
        self.assertEqual((game / 'personal-save.txt').read_text(), 'keep me')
        with self.assertRaises(urllib.error.HTTPError) as error:
            self.start_repair({'magnet': magnet, 'folder': str(game)})
        self.assertEqual(error.exception.code, 409)
        self.api('/remove', {'id': tid, 'delete_files': False})
        self.assertTrue((game / 'good.bin').exists())

    def test_renamed_external_repack_without_manifest(self):
        name, contents, ti, tid, magnet = self.fixture('renamed')
        folder = WORK / 'external-download' / 'My renamed game'
        folder.mkdir(parents=True)
        (folder / 'good.bin').write_bytes(contents['good.bin'])
        (folder / 'bad.bin').write_bytes(b'x' * len(contents['bad.bin']))
        (folder / 'keep.txt').write_text('preserve')
        self.api('/repair/scan', {'magnet': magnet, 'folder': str(folder.parent)})
        obj = engine.torrents[tid]
        wait_for(lambda: obj.get('report') is not None)
        states = {Path(f['name']).name: f['status'] for f in obj['report']['files']}
        self.assertEqual(states, {'good.bin': 'ok', 'bad.bin': 'damaged', 'missing.bin': 'missing'})
        self.assertEqual(obj['handle'].status().total_payload_download, 0)
        self.assertTrue(obj['report']['identity_confirmed'])
        self.api('/repair/confirm', {'id': tid})
        listing = next(t for t in json.load(urllib.request.urlopen(self.url + '/list')) if t['id'] == tid)
        self.assertEqual(len(listing['files']), len(contents))
        obj['handle'].connect_peer(('127.0.0.1', self.seed.listen_port()))
        wait_for(lambda: obj['is_moved'])
        for relative, data in contents.items():
            self.assertEqual((folder / relative).read_bytes(), data)
        self.assertEqual((folder / 'keep.txt').read_text(), 'preserve')
        self.assertFalse((folder.parent / name).exists())
        self.assertTrue((folder / '.mn-game.json').exists())
        self.api('/remove', {'id': tid, 'delete_files': False})

    def test_wrong_game_shared_names_cannot_confirm(self):
        payload = {'fg-01.bin': os.urandom(65536), 'fg-02.bin': os.urandom(65536),
                   'setup.exe': os.urandom(65536), 'MD5/QuickSFV.EXE': os.urandom(65536)}
        name, contents, ti, tid, magnet = self.fixture('identity', payload)
        folder = WORK / 'wrong-game' / 'Assassins Creed unrelated'
        folder.mkdir(parents=True)
        for relative, data in contents.items():
            file = folder / relative
            file.parent.mkdir(parents=True, exist_ok=True)
            file.write_bytes(b'wrong' * 20000 if relative.endswith('.bin') else data)
        before = {str(f.relative_to(folder)): f.read_bytes() for f in folder.rglob('*') if f.is_file()}
        result = self.api('/repair/scan', {'magnet': magnet, 'folder': str(folder)})
        obj = engine.torrents[tid]
        wait_for(lambda: obj.get('report') is not None)
        self.assertFalse(obj['report']['identity_confirmed'], 'shared setup and QuickSFV must not prove identity')
        with self.assertRaises(urllib.error.HTTPError) as denied:
            self.api('/repair/confirm', {'id': tid})
        self.assertEqual(denied.exception.code, 409)
        self.assertEqual(obj['handle'].status().total_payload_download, 0)
        for relative, data in before.items():
            self.assertEqual((folder / relative).read_bytes(), data, 'wrong folder is untouched')
        self.api('/repair/cancel', {'id': tid})

    def test_02_normal_download_move_and_verify(self):
        name, contents, ti, tid, magnet = self.fixture('normal')
        source, target = WORK / 'temp', WORK / 'destination'
        source.mkdir()
        target.mkdir()
        self.api('/add', {'magnet': magnet, 'save_path': str(source), 'target_path': str(target)})
        obj = engine.torrents[tid]
        obj['handle'].connect_peer(('127.0.0.1', self.seed.listen_port()))
        wait_for(lambda: obj['is_moved'], 45)
        self.assertTrue(obj['is_verified'])
        for relative, data in contents.items():
            self.assertEqual((target / name / relative).read_bytes(), data)
        self.api('/remove', {'id': tid, 'delete_files': False})

    def test_03_folder_safety(self):
        base = WORK / 'discovery'
        (base / 'a' / 'Game').mkdir(parents=True)
        (base / 'a' / 'Game' / 'data.bin').write_bytes(b'123')
        files = [{'name': 'Game/data.bin', 'size': 3}]
        self.assertEqual(find_save_path(base, files), str(base / 'a'))
        self.assertEqual(find_save_path(base / 'a' / 'Game', files), str(base / 'a'))
        (base / 'b' / 'Game').mkdir(parents=True)
        (base / 'b' / 'Game' / 'data.bin').write_bytes(b'456')
        with self.assertRaisesRegex(ValueError, 'Multiple'):
            find_save_path(base, files)
        with self.assertRaises(ValueError):
            safe_file(base, '../escape')
        with self.assertRaises(ValueError):
            safe_file(base, 'C:/escape')
        with self.assertRaisesRegex(ValueError, 'No matching'):
            find_save_path(base, [{'name': 'Other/file.bin', 'size': 3}])

    def test_04_healthy_files_and_oversized_file(self):
        name, contents, ti, tid, magnet = self.fixture('healthy')
        folder = WORK / 'healthy-library' / name
        folder.mkdir(parents=True)
        for relative, data in contents.items():
            file = folder / relative
            file.parent.mkdir(parents=True, exist_ok=True)
            file.write_bytes(data + (b'extra bytes' if relative == 'bad.bin' else b''))
        inspection = self.api('/inspect', {'magnet': magnet})
        self.assertTrue(inspection['has_metadata'])
        self.assertEqual(inspection['total_size'], sum(map(len, contents.values())))
        self.assertEqual(inspection['files_count'], 3)
        self.start_repair({'magnet': magnet, 'folder': str(folder)})
        obj = engine.torrents[tid]
        wait_for(lambda: obj['is_moved'])
        self.assertTrue(obj['is_verified'])
        self.assertEqual(obj['handle'].status().total_payload_download, 0)
        for relative, data in contents.items():
            self.assertEqual((folder / relative).read_bytes(), data)
        # Removing a repair task must preserve the user's existing files even when requested.
        self.api('/remove', {'id': tid, 'delete_files': True})
        self.assertTrue((folder / 'good.bin').exists())

    def test_05_resume_data_roundtrip(self):
        name, contents, ti, tid, magnet = self.fixture('resume')
        folder = WORK / 'resume-library' / name
        folder.mkdir(parents=True)
        (folder / 'good.bin').write_bytes(contents['good.bin'])
        self.start_repair({'magnet': magnet, 'folder': str(folder)})
        obj = engine.torrents[tid]
        wait_for(lambda: obj['is_repairing'])
        self.api('/pause', {'id': tid})
        obj['handle'].save_resume_data(lt.save_resume_flags_t.flush_disk_cache)
        resume = Path(engine.RESUME_DIR) / (tid + '.fastresume')
        wait_for(lambda: resume.exists() and resume.stat().st_size > 0)
        params = lt.read_resume_data(resume.read_bytes())
        self.assertEqual(Path(params.save_path), folder.parent)
        self.assertTrue(params.flags & lt.torrent_flags.paused)
        self.api('/resume', {'id': tid})
        obj['handle'].connect_peer(('127.0.0.1', self.seed.listen_port()))
        wait_for(lambda: obj['is_moved'])
        self.assertTrue(obj['is_verified'])
        self.api('/remove', {'id': tid, 'delete_files': False})

    def test_06_preview_requires_confirmation_and_writes_manifest(self):
        name, contents, ti, tid, magnet = self.fixture('preview')
        folder = WORK / 'preview-library' / name
        folder.mkdir(parents=True)
        (folder / 'good.bin').write_bytes(contents['good.bin'])
        (folder / 'bad.bin').write_bytes(b'x' * len(contents['bad.bin']))
        self.api('/repair/scan', {'magnet': magnet, 'folder': str(folder)})
        obj = engine.torrents[tid]
        wait_for(lambda: obj.get('report') is not None)
        report = self.api('/repair/status', {'id': tid})['report']
        states = {f['name'].replace('\\', '/'): f['status'] for f in report['files']}
        self.assertEqual(states[name + '/good.bin'], 'ok')
        self.assertEqual(states[name + '/bad.bin'], 'damaged')
        self.assertEqual(states[name + '/nested/missing.bin'], 'missing')
        self.assertEqual((folder / 'bad.bin').read_bytes(), b'x' * 65536)
        self.assertEqual(obj['handle'].status().total_payload_download, 0)
        self.assertFalse((folder / '.mn-game.json').exists())
        self.api('/repair/confirm', {'id': tid})
        wait_for(lambda: obj['is_repairing'])
        obj['handle'].connect_peer(('127.0.0.1', self.seed.listen_port()))
        wait_for(lambda: obj['is_moved'])
        manifest = json.loads((folder / '.mn-game.json').read_text())
        self.assertEqual(manifest['infohash'], tid)
        self.assertEqual(manifest['total_size'], 196608)
        self.assertEqual(len(manifest['files']), 3)
        for entry in manifest['files']:
            self.assertEqual(entry['sha256'], hashlib.sha256(contents[entry['path']]).hexdigest())
        self.assertTrue((folder / '.mn-package.torrent').exists())
        self.api('/remove', {'id': tid, 'delete_files': False})
        # Offline follow-up scan uses the saved torrent, but still hashes real files.
        engine.metadata_cache.pop(tid)
        self.api('/repair/scan', {'magnet': magnet, 'folder': str(folder)})
        wait_for(lambda: engine.torrents[tid].get('report') is not None)
        self.assertTrue(engine.torrents[tid]['report']['all_ok'])
        self.api('/repair/cancel', {'id': tid})
        self.assertTrue((folder / 'good.bin').exists())

    def test_07_explicit_pause_state(self):
        name, contents, ti, tid, magnet = self.fixture('pause-state')
        self.api('/add', {'magnet': magnet, 'save_path': str(WORK / 'paused-state')})
        obj = engine.torrents[tid]
        self.assertFalse(bool(obj['handle'].status().flags & lt.torrent_flags.paused))
        self.assertFalse(obj.get('user_paused', False))
        self.api('/pause', {'id': tid})
        self.assertTrue(obj['user_paused'])
        self.api('/resume', {'id': tid})
        self.assertFalse(obj['user_paused'])
        self.api('/remove', {'id': tid, 'delete_files': False})

    def test_08_live_metadata_inspection(self):
        name, contents, ti, tid, magnet = self.fixture('inspection')
        engine.metadata_cache.pop(tid)
        def connect_inspection():
            end = time.monotonic() + 10
            while time.monotonic() < end:
                for handle in engine.ses.get_torrents():
                    if str(handle.info_hash()) == tid:
                        handle.connect_peer(('127.0.0.1', self.seed.listen_port()))
                        return
                time.sleep(.05)
        connector = threading.Thread(target=connect_inspection, daemon=True)
        connector.start()
        result = self.api('/inspect', {'magnet': magnet, 'timeout': 15})
        self.assertTrue(result['has_metadata'], result)
        self.assertEqual(result['total_size'], 196608)
        self.assertEqual(result['files_count'], 3)
        self.assertIn(tid, engine.metadata_cache)


if __name__ == '__main__':
    unittest.main(argv=['test_engine'], verbosity=2)